# -*- coding: utf-8 -*-
"""Butir pembatalan perkawinan bagian A: hubungan saksi, kedudukan Penggugat, akad dan pencatatan, alasan huruf A (poligami tanpa izin). Agen W2b-C."""
from isi_pembatalan import S

TIDAK_NIAT = ['de-auditu', 'sebagian', 'mendengar', 'tidak-tahu', 'ragu']  # butir tentang diri saksi sendiri: hanya keterangan langsung

# ------------------------------------------------------------------ hubungan saksi (urutan 12)
S(id='kenal-lama', pokok='pp-bt-cara-kenal', urut_abs=12, tingkat='pilihan', kelompok='hubungan', tidakBerlaku=TIDAK_NIAT,
  teks='Sudah berapa lama saksi mengenal {PAS} dan bagaimana saksi biasa bertemu dengan mereka?',
  varian=['Sejak kapan saksi mengenal {PAS} dan seberapa sering saksi bertemu dengan mereka?'],
  hal='perkenalan saksi dengan {PAS}', m='lamanya perkenalan dan pergaulan saksi dengan {PAS}', fam='tahu',
  K=(['{PAS} sudah lama menjadi orang yang saya kenal dan kami sering bertemu dalam pergaulan sehari-hari',
      '{PAS} sudah bertahun-tahun menjadi tetangga saya dan hampir setiap pekan kami bertemu'],
     ['perkenalan saya dengan {PAS} sudah cukup lama dan kami biasa bertemu di lingkungan tempat tinggal',
      'saya mengenal {PAS} dari pergaulan di kampung dan kami sering berjumpa pada acara warga']),
  peran={'keluarga-pengaju': (['saya masih keluarga #0046# dan sudah lama mengenal #0046# serta #0047# dari pertemuan keluarga yang sering kami hadiri',
                               'sebagai kerabat #0046# saya sering berkunjung ke rumahnya dan dari situ saya mengenal #0047#',
                               'saya bagian dari keluarga #0046# sehingga saya mengenal #0046# sejak lama dan #0047# sejak ia dikenal keluarga kami',
                               'karena masih sekeluarga dengan #0046# saya mengenal #0046# maupun #0047# dengan cukup baik'],
                              ['hubungan saya dengan #0046# adalah hubungan keluarga dan saya mengenal #0047# melalui #0046# dan acara keluarga',
                               'saya termasuk kerabat dekat #0046# dan hampir tiap ada acara keluarga saya bertemu dengan #0046# dan #0047#',
                               'sebagai bagian dari keluarga #0046# saya sudah lama tahu siapa #0046# dan siapa #0047#',
                               'saya sekeluarga dengan #0046# dan mengenal #0047# dari kunjungan serta pertemuan keluarga']),
         'keluarga-lawan': (['saya masih keluarga #0047# dan sudah lama mengenal #0047# serta #0046# dari pertemuan keluarga yang sering kami hadiri',
                             'sebagai kerabat #0047# saya sering berkunjung ke rumahnya dan dari situ saya mengenal #0046#',
                             'saya bagian dari keluarga #0047# sehingga saya mengenal #0047# sejak lama dan #0046# sejak ia dikenal keluarga kami',
                             'karena masih sekeluarga dengan #0047# saya mengenal #0047# maupun #0046# dengan cukup baik'],
                            ['hubungan saya dengan #0047# adalah hubungan keluarga dan saya mengenal #0046# melalui #0047# dan acara keluarga',
                             'saya termasuk kerabat dekat #0047# dan hampir tiap ada acara keluarga saya bertemu dengan #0047# dan #0046#',
                             'sebagai bagian dari keluarga #0047# saya sudah lama tahu siapa #0047# dan siapa #0046#',
                             'saya sekeluarga dengan #0047# dan mengenal #0046# dari kunjungan serta pertemuan keluarga'])})

# ------------------------------------------------------------------ kedudukan Penggugat (22-26)
S(id='pengaju-keluarga-lurus', pokok='pp-bt-hak-keluarga', urut_abs=22, tingkat='inti', keadaan={'kedudukanPengaju': 'keluarga'},
  teks='Apa hubungan keluarga antara #0046# dengan salah seorang suami atau istri dalam perkawinan yang dimohonkan pembatalannya, dan apakah garis keturunannya lurus ke atas?',
  varian=['Termasuk keluarga yang mana #0046# bagi suami atau istri dalam perkawinan itu, dan apakah ia orang tua atau leluhur dari salah satunya?'],
  hal='hubungan keluarga #0046# dengan suami atau istri dalam perkawinan yang dimohonkan pembatalan', m='hubungan keluarga #0046# dengan suami atau istri dalam perkawinan itu', fam='tahu',
  K=(['#0046# termasuk keluarga dalam garis keturunan lurus ke atas dari salah seorang yang menikah dalam perkawinan itu',
      'salah seorang mempelai dalam perkawinan itu adalah keturunan langsung #0046# dan hubungan darah mereka lurus'],
     ['antara #0046# dengan salah seorang mempelai ada hubungan darah lurus ke atas sehingga #0046# adalah leluhur langsungnya',
      'dalam silsilah keluarga #0046# berada pada garis lurus ke atas dari salah satu mempelai yang menikah itu']),
  P=(['#0046# adalah keluarga dari salah seorang mempelai dalam perkawinan itu', 'salah satu mempelai dalam perkawinan itu masih keluarga #0046#'],
     ['#0046# punya hubungan keluarga dengan salah satu mempelai dalam perkawinan itu', 'hubungan keluarga #0046# dengan salah seorang mempelai sudah saya ketahui']),
  A=['#0046# adalah orang tua kandung dari salah satu mempelai', 'salah satu mempelai adalah anak kandung #0046#'],
  B=['#0046# hanya kerabat jauh dari salah satu mempelai', 'hubungan #0046# dengan salah satu mempelai adalah sepupu'],
  beda_pada='peristiwa', beda_maksud='versi A: Penggugat orang tua kandung salah satu mempelai; versi B: hanya kerabat jauh - berselisih pada PERISTIWA (derajat hubungan keluarga)')

S(id='pengaju-pasangan-sah', pokok='pp-bt-hak-pasangan', urut_abs=24, tingkat='inti', keadaan={'kedudukanPengaju': 'suami-istri'},
  teks='Apakah #0046# memang suami atau istri yang sah yang terkait dengan perkawinan ini, dan apakah ikatan perkawinan #0046# itu masih berlangsung sampai sekarang?',
  varian=['Sejak kapan #0046# menjadi suami atau istri yang sah dalam perkawinan ini, dan apakah #0046# masih terikat dalam perkawinan itu sampai sekarang?'],
  hal='status #0046# sebagai suami atau istri yang sah', m='status #0046# sebagai suami atau istri yang sah dan masih berlangsungnya ikatan itu', fam='tahu',
  K=(['#0046# adalah suami atau istri yang sah dalam perkawinan itu dan ikatan perkawinannya masih berlangsung sampai sekarang',
      'sejak menikah #0046# berstatus sebagai suami atau istri yang sah dan statusnya itu masih berlaku hingga kini'],
     ['ikatan perkawinan #0046# yang sah masih berjalan sampai sekarang dan #0046# memang suami atau istri dalam perkawinan itu',
      'status #0046# sebagai suami atau istri yang sah tetap ada dan perkawinannya masih berlanjut']),
  P=(['#0046# adalah suami atau istri yang sah dalam perkawinan itu', '#0046# sejak menikah berstatus suami atau istri yang sah'],
     ['ikatan perkawinan #0046# yang sah memang ada', 'status #0046# sebagai suami atau istri yang sah tetap ada']))

S(id='pengaju-kepentingan', pokok='pp-bt-kepentingan', urut_abs=26, tingkat='inti', keadaan={'kedudukanPengaju': 'berkepentingan'},
  teks='Apa kepentingan #0046# atas perkawinan yang dimohonkan pembatalannya, dan apa kerugian yang dialami #0046# bila perkawinan itu tetap berlangsung?',
  varian=['Mengapa #0046# merasa berkepentingan untuk membatalkan perkawinan itu dan kerugian apa yang akan dialami #0046# bila perkawinan itu dibiarkan?'],
  hal='kepentingan #0046# atas perkawinan yang dimohonkan pembatalannya', m='kepentingan dan kerugian #0046# atas perkawinan yang dimohonkan pembatalannya', fam='tahu',
  K=(['#0046# berkepentingan langsung atas perkawinan itu karena perkawinan tersebut merugikan hak dan kedudukannya',
      'perkawinan itu menyentuh hak #0046# secara langsung sehingga #0046# merasa dirugikan bila tetap berlangsung'],
     ['kerugian yang dirasakan #0046# akibat perkawinan itu nyata dan berkaitan dengan hak serta kedudukannya',
      '#0046# dirugikan oleh perkawinan itu dan karena itu ia berkepentingan untuk membatalkannya']),
  P=(['#0046# punya kepentingan atas perkawinan itu', 'perkawinan itu berkaitan dengan hak #0046#'],
     ['kepentingan #0046# atas perkawinan itu memang ada', '#0046# merasa perkawinan itu menyangkut dirinya']),
  A=['#0046# dirugikan karena haknya atas harta terkena perkawinan itu', 'harta #0046# terancam oleh perkawinan itu'],
  B=['#0046# dirugikan karena nama baik keluarganya tercoreng oleh perkawinan itu', 'perkawinan itu menodai nama baik keluarga #0046#'],
  beda_pada='penyebab', beda_maksud='versi A: kerugian berupa hak atas harta; versi B: kerugian berupa nama baik keluarga - berselisih pada PENYEBAB kerugian')

# ------------------------------------------------------------------ akad dan pencatatan (32-36)
S(id='akad-penikah-hadirin', pokok='pp-bt-akad', urut_abs=32, tingkat='pilihan',
  teks='Siapa yang bertindak menikahkan {PAS} dan siapa saja yang hadir pada akad nikah itu?',
  varian=['Siapa saja yang hadir ketika {PAS} menjalani akad nikah dan siapa yang menikahkan mereka?'],
  hal='orang yang menikahkan dan hadirin pada akad nikah {PAS}', m='orang yang menikahkan dan hadirin pada akad nikah {PAS}', fam='hadir',
  K=(['{PAS} dinikahkan oleh orang yang bertindak sebagai wali atau wakil wali di hadapan keluarga dan para tetangga',
      'akad nikah {PAS} dilakukan oleh seorang yang menikahkan mereka dan dihadiri keluarga serta warga sekitar'],
     ['yang menikahkan {PAS} adalah orang yang menjadi wali atau wakilnya dan banyak orang hadir pada akad itu',
      'pada akad nikah {PAS} ada orang yang bertindak menikahkan dan sejumlah keluarga serta tetangga menyaksikannya']),
  P=(['{PAS} dinikahkan oleh seorang yang bertindak sebagai wali atau wakilnya', 'akad nikah {PAS} dihadiri keluarga'],
     ['ada orang yang bertindak menikahkan {PAS} pada akad itu', 'banyak orang hadir pada akad nikah {PAS}']),
  M=(['orang yang menikahkan mengucapkan ijab di hadapan hadirin dan mempelai pria menjawab dengan kabul',
      'ijab diucapkan oleh yang menikahkan lalu kabul diucapkan oleh mempelai pria'],
     ['yang menikahkan mengucapkan lafaz ijab dan mempelai pria mengucapkan kabul di depan para hadirin',
      'lafaz ijab dari yang menikahkan dijawab dengan lafaz kabul oleh mempelai pria']))

S(id='buku-nikah-pegang', pokok='pp-bt-pencatatan', urut_abs=34, tingkat='pilihan', keadaan={'pencatatan': 'tercatat'},
  teks='Apakah {PAS} memegang buku nikah atau kutipan akta nikah dari Kantor Urusan Agama dan siapa yang menyimpannya sekarang?',
  varian=['Siapa yang menyimpan buku nikah milik {PAS} sekarang dan apakah saksi pernah melihat buku nikah itu?'],
  hal='buku nikah {PAS}', m='buku nikah atau kutipan akta nikah {PAS}', fam='tahu',
  K=(['{PAS} mendapat buku nikah dari Kantor Urusan Agama dan buku itu sampai sekarang masih disimpan oleh salah satu dari mereka',
      'perkawinan {PAS} tercatat dan mereka menerima kutipan akta nikah yang kini disimpan oleh salah satu pihak'],
     ['buku nikah {PAS} sudah diterbitkan Kantor Urusan Agama dan sekarang dipegang salah seorang di antara mereka',
      'kutipan akta nikah {PAS} ada dan tersimpan pada salah satu pihak sampai hari ini']),
  P=(['{PAS} mendapat buku nikah dari Kantor Urusan Agama', 'perkawinan {PAS} tercatat dan ada kutipan akta nikahnya'],
     ['buku nikah {PAS} sudah diterbitkan Kantor Urusan Agama', 'kutipan akta nikah {PAS} memang ada']),
  A=['buku nikah itu dipegang oleh #0046#', '#0046# yang menyimpan buku nikah itu'],
  B=['buku nikah itu dipegang oleh #0047#', '#0047# yang menyimpan buku nikah itu'],
  beda_pada='pelaku', beda_maksud='versi A: buku nikah dipegang Penggugat; versi B: dipegang Tergugat - berselisih pada PELAKU yang menyimpan buku nikah')

S(id='nikah-tidak-dicatat', pokok='pp-bt-pencatatan', urut_abs=36, tingkat='inti', keadaan={'pencatatan': 'tidak-tercatat'},
  teks='Mengapa perkawinan {PAS} tidak didaftarkan pada Kantor Urusan Agama dan siapa saja yang mengetahui perkawinan itu?',
  varian=['Apakah perkawinan {PAS} dicatat oleh Pegawai Pencatat Nikah, dan bila tidak apa sebabnya serta siapa yang menyaksikannya?'],
  hal='sebab perkawinan {PAS} tidak dicatat', m='tidak dicatatnya perkawinan {PAS} dan orang yang mengetahuinya', fam='tahu',
  K=(['perkawinan {PAS} tidak didaftarkan pada Kantor Urusan Agama dan hanya diketahui keluarga serta orang-orang dekat',
      'akad nikah {PAS} dilakukan tanpa pencatatan oleh Pegawai Pencatat Nikah dan yang mengetahuinya hanya keluarga dan kenalan dekat'],
     ['pencatatan perkawinan {PAS} tidak pernah dilakukan dan hanya keluarga serta kerabat dekat yang mengetahui perkawinan itu',
      'perkawinan {PAS} tidak tercatat di Kantor Urusan Agama dan orang yang tahu hanyalah keluarga serta teman dekat']),
  P=(['perkawinan {PAS} tidak didaftarkan pada Kantor Urusan Agama', 'akad nikah {PAS} dilakukan tanpa pencatatan'],
     ['pencatatan perkawinan {PAS} tidak pernah dilakukan', 'perkawinan {PAS} tidak tercatat di Kantor Urusan Agama']))

# ------------------------------------------------------------------ alasan huruf A: poligami tanpa izin (42-46)
S(id='a-istri-pertama-sikap', pokok='pp-bt-poligami', urut_abs=42, tingkat='inti', keadaan={'alasan': 'A'},
  teks='Apakah istri pertama pernah dimintai persetujuan oleh suaminya sebelum suami itu menikah lagi, dan bagaimana sikap istri pertama terhadap perkawinan yang baru itu?',
  varian=['Apakah sebelum menikah lagi suami meminta persetujuan istri pertamanya, dan bagaimana sikap istri pertama ketika mengetahui perkawinan baru itu?'],
  hal='persetujuan dan sikap istri pertama atas perkawinan suaminya yang baru', m='persetujuan dan sikap istri pertama atas perkawinan suaminya yang baru', fam='tahu',
  K=(['istri pertama tidak pernah dimintai persetujuan oleh suaminya dan ia menolak perkawinan yang baru itu',
      'suami menikah lagi tanpa persetujuan istri pertamanya dan istri pertama keberatan atas perkawinan itu'],
     ['persetujuan istri pertama tidak pernah diminta dan ia keberatan setelah perkawinan baru itu diketahuinya',
      'istri pertama tidak diberi kesempatan menyatakan setuju dan ia menolak perkawinan suaminya yang baru']),
  P=(['istri pertama tidak pernah dimintai persetujuan oleh suaminya', 'suami menikah lagi tanpa persetujuan istri pertamanya'],
     ['persetujuan istri pertama tidak pernah diminta', 'istri pertama tidak diberi kesempatan menyatakan setuju']),
  M=(['istri pertama mengatakan bahwa ia tidak pernah dimintai persetujuan dan ia tidak setuju suaminya menikah lagi',
      'istri pertama berkata ia tidak pernah diminta persetujuan dan tidak merelakan suaminya menikah lagi'],
     ['dengan suara keras istri pertama mengatakan bahwa tidak ada yang meminta persetujuannya dan ia tidak rela suaminya menikah lagi',
      'istri pertama menyatakan tidak pernah diminta izin dan tidak mau suaminya beristri lagi']),
  A=['istri pertama sama sekali tidak diberi tahu sebelum perkawinan itu berlangsung', 'sebelum perkawinan itu istri pertama tidak mengetahui apa-apa'],
  B=['istri pertama sudah diberi tahu tetapi menolak', 'istri pertama sudah tahu rencana itu namun menolak merestui'],
  beda_pada='peristiwa', beda_maksud='versi A: istri pertama sama sekali tidak diberi tahu; versi B: sudah diberi tahu tetapi menolak - berselisih pada PERISTIWA (pemberitahuan kepada istri pertama)')

S(id='a-izin-pengadilan', pokok='pp-bt-poligami', urut_abs=44, tingkat='inti', keadaan={'alasan': 'A'},
  teks='Apakah suami pernah mengajukan permohonan izin beristri lebih dari seorang kepada Pengadilan Agama sebelum menikah lagi, dan apakah saksi pernah melihat penetapan izin dari pengadilan?',
  varian=['Sebelum menikah lagi apakah suami pernah mengurus izin poligami ke Pengadilan Agama, dan apakah ada surat penetapannya yang pernah saksi lihat?'],
  hal='izin Pengadilan Agama untuk suami menikah lagi', m='izin Pengadilan Agama untuk suami menikah lagi', fam='tahu',
  K=(['suami tidak pernah mengurus izin beristri lebih dari seorang ke Pengadilan Agama sebelum menikah lagi',
      'sebelum menikah lagi suami menikah tanpa penetapan izin dari Pengadilan Agama'],
     ['suami menikah lagi tanpa pernah memperoleh penetapan izin poligami dari Pengadilan Agama',
      'tidak pernah ada permohonan izin poligami dari suami yang diajukan ke Pengadilan Agama']),
  P=(['suami tidak pernah mengurus izin poligami ke Pengadilan Agama', 'suami menikah lagi tanpa penetapan izin dari Pengadilan Agama'],
     ['tidak pernah ada permohonan izin poligami dari suami', 'suami menikah lagi tanpa pernah memperoleh izin dari pengadilan']),
  A=['suami tidak pernah mengajukan izin ke pengadilan', 'tidak pernah ada permohonan izin dari suami'],
  B=['suami pernah mengajukan izin tetapi permohonan itu ditolak', 'permohonan izin suami pernah diajukan namun ditolak oleh pengadilan'],
  beda_pada='peristiwa', beda_maksud='versi A: suami tidak pernah mengajukan izin; versi B: pernah mengajukan tetapi ditolak - berselisih pada PERISTIWA (pengajuan izin)')

S(id='a-masih-terikat-istri-pertama', pokok='pp-bt-poligami', urut_abs=46, tingkat='pilihan', keadaan={'alasan': 'A'},
  teks='Apakah ketika menikah lagi suami masih terikat perkawinan yang sah dengan istri pertama dan sampai sekarang apakah istri pertama itu masih berstatus istrinya?',
  varian=['Sejak kapan suami terikat perkawinan dengan istri pertama, dan apakah perkawinan itu masih utuh ketika suami menikah lagi?'],
  hal='status perkawinan suami dengan istri pertama ketika ia menikah lagi', m='status perkawinan suami dengan istri pertama ketika ia menikah lagi', fam='tahu',
  K=(['ketika suami menikah lagi ia masih terikat perkawinan yang sah dengan istri pertama dan perkawinan itu masih berlangsung',
      'perkawinan suami dengan istri pertama masih utuh pada hari ia menikah lagi dan ikatan itu masih sah sampai sekarang'],
     ['pada hari suami menikah lagi istri pertama masih berstatus istrinya yang sah',
      'istri pertama masih menjadi istri sah suami ketika ia melangsungkan perkawinan yang baru dan statusnya itu berlanjut hingga kini']),
  P=(['suami masih terikat perkawinan dengan istri pertama ketika ia menikah lagi', 'perkawinan suami dengan istri pertama masih utuh pada hari ia menikah lagi'],
     ['istri pertama masih berstatus istri sah suami pada hari itu', 'istri pertama masih menjadi istri sah ketika suami menikah lagi']))
